/* Persistent selected-target chip: visible only after the user explicitly picks
   a target. The best sim row is a reference, not the chosen real-world wing. */
function TargetChip({ sel, picked, baseline, accMap, noise, goBalance, open, setOpen }) {
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDown = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const onKey = (e) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("pointerdown", onDown); document.removeEventListener("keydown", onKey); };
  }, [open, setOpen]);
  if (!sel) return null;
  return (
    <div className="relative" ref={ref}>
      <button onClick={() => setOpen(!open)} aria-expanded={open} aria-haspopup="true"
        className="border px-2 py-1 hover:opacity-90 focus:outline-none text-left whitespace-nowrap"
        style={{ fontSize: FS.sm, borderColor: P.amber, background: "#fff7f0", color: P.text }}>
        <span style={{ color: P.faint }}>TARGET </span><span className="font-mono">{tripleU(sel)}</span>
        <span style={{ color: P.amber, fontWeight: 700 }}> · {fmt(sel.total, 1)} pts</span>
        <span style={{ color: P.faint }}> · L/D {fmt(sel.ld, 1)}</span>
        <span style={{ color: P.faint }}> {open ? "▴" : "▾"}</span>
      </button>
      {open && (
        <div className="absolute right-0 z-50 border p-3" style={{ top: "calc(100% + 6px)", width: 330, background: P.panel, borderColor: P.line2, boxShadow: "0 6px 18px rgba(0,0,0,0.18)" }}>
          {baseline && (
            <div className="mb-2" style={{ fontSize: FS.cap, color: P.faint }}>
              Δ vs reference build <span className="font-mono">{triple(baseline)}</span>
            </div>
          )}
          <CaseDetail row={sel} baseline={baseline} accMap={accMap} noise={noise}
            goBalance={(r) => { setOpen(false); goBalance(r); }} />
        </div>
      )}
    </div>
  );
}

/* ── data drawer: the actual tables behind every chart, inspectable ── */
const WB_COLS = [
  ["cl", "CL", 3], ["cd", "CD", 4], ["cop", "CoP", 3], ["total", "total", 1],
  ["endur", "endur", 1], ["auto", "auto", 1], ["skid", "skid", 1], ["accel", "accel", 1],
  ["t_endur", "t endur", 2], ["t_auto", "t auto", 2], ["t_skid", "t skid", 3], ["t_accel", "t accel", 3],
  ["ld", "L/D", 2],
];

function DataDrawer({ open, setOpen, sweep, trace, tab, pageCop, sel, onSel }) {
  const [view, setView] = useState("workbook");
  const [copF, setCopF] = useState("page"); // "page" (mirror explorer slice) | "all"
  const [modeF, setModeF] = useState("F");
  const [sort, setSort] = useState({ k: "total", dir: -1 });
  const evs = trace ? Object.keys(trace) : [];
  const [ev, setEv] = useState(evs[0] || "endurance");
  // resync the event pick when a new trace lands without this event
  useEffect(() => {
    if (trace && !trace[ev]) { const k = Object.keys(trace); if (k.length) setEv(k[0]); }
  }, [trace, ev]);
  const copActive = view === "workbook" && copF === "page" && tab === "explore" && pageCop != null;
  const rows = useMemo(() => {
    let r = sweep;
    if (modeF !== "all") r = r.filter((x) => x.mode === modeF);
    if (copActive) r = r.filter((x) => eq(x.cop, pageCop) || isRef(x));
    return [...r].sort((a, b) => (a[sort.k] == null ? 1 : b[sort.k] == null ? -1 : (a[sort.k] - b[sort.k]) * sort.dir));
  }, [sweep, modeF, copActive, pageCop, sort]);
  const T = trace && trace[ev] ? trace[ev] : evs.length ? trace[evs[0]] : null;
  // trace sorting works on an index permutation over the parallel arrays
  const traceIdx = useMemo(() => {
    if (!T) return [];
    const idx = Array.from({ length: T.t.length }, (_, i) => i);
    if (view === "trace" && Array.isArray(T[sort.k]))
      idx.sort((a, b) => (T[sort.k][a] - T[sort.k][b]) * sort.dir);
    return idx;
  }, [T, sort, view]);
  // clicking a workbook row selects that aero target (maps reruns to their
  // fast row so the grid + scorecard line up)
  const selectRow = (r) => onSel(sweep.find((x) => x.mode === "F" && keyOf(x) === keyOf(r)) || r);
  const th = (k, label, alignL) => (
    <th key={k} className={(alignL ? "text-left" : "text-right") + " font-normal px-1.5 cursor-pointer select-none whitespace-nowrap"}
      onClick={() => setSort((s) => ({ k, dir: s.k === k ? -s.dir : -1 }))}
      style={{ color: sort.k === k ? P.amber : P.faint, position: "sticky", top: 0, background: P.panel2 }}>
      {label}{sort.k === k ? (sort.dir < 0 ? " ↓" : " ↑") : ""}
    </th>
  );
  return (
    <div className="mb-3" style={{ border: "1px solid " + (open ? P.line2 : P.amber), background: P.panel }}>
      {/* prominent toggle — reads clearly as "open the data tables" */}
      <button onClick={() => setOpen(!open)}
        className="w-full flex items-center gap-3 px-3 py-2 text-left focus:outline-none hover:opacity-95"
        style={{ background: open ? P.panel : "#fff7f0" }}>
        <span className="flex items-center justify-center" style={{ width: 22, height: 22, background: P.amber, color: "#fff", fontSize: FS.base, flexShrink: 0 }} aria-hidden>⊞</span>
        <span className="font-display font-semibold uppercase" style={{ fontSize: FS.title, letterSpacing: "0.04em", color: P.text }}>
          {open ? "Data tables" : "Inspect the data"}
        </span>
        <span style={{ fontSize: FS.sm, color: P.dim }}>
          {sweep.length} workbook rows{evs.length ? " · " + evs.map((e) => trace[e].src.toLocaleString()).join("+") + " trace samples" : ""}
        </span>
        <span className="flex-1" />
        <span className="border px-2 py-0.5" style={{ fontSize: FS.cap, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: open ? P.dim : P.amber, borderColor: open ? P.line2 : P.amber }}>
          {open ? "▴ collapse" : "▾ open tables"}
        </span>
      </button>
      {open && (
        <div className="border-t px-3 py-2" style={{ borderColor: P.line }}>
          <div className="flex flex-wrap items-center gap-2">
            <Chip on={view === "workbook"} onClick={() => setView("workbook")}>workbook</Chip>
            <Chip on={view === "trace"} onClick={() => setView("trace")}>trace</Chip>
            <span style={{ color: P.line2 }}>|</span>
            {view === "workbook" ? (
              <>
                {tab === "explore" && pageCop != null && (
                  <Chip on={copF === "page"} onClick={() => setCopF("page")}>
                    {"this page: CoP " + pageCop.toFixed(3) + " slice"}
                  </Chip>
                )}
                <Chip on={!copActive} onClick={() => setCopF("all")}>all rows</Chip>
                <span style={{ color: P.line2 }}>|</span>
                {[["F", "fast"], ["A", "rerun"], ["all", "both"]].map(([k, l]) => (
                  <Chip key={k} on={modeF === k} onClick={() => setModeF(k)}>{l}</Chip>
                ))}
              </>
            ) : (
              evs.map((e) => <Chip key={e} on={ev === e} onClick={() => setEv(e)}>{e}</Chip>)
            )}
            <span className="flex-1" />
            <span style={{ fontSize: FS.cap, color: P.dim }}>
              {view === "workbook" ? rows.length + " rows" : T ? T.kept.toLocaleString() + " of " + T.src.toLocaleString() + " samples (downsampled)" : "no trace"}
            </span>
          </div>
          {/* SCROLL, not paginate — sticky header, all rows in view */}
          <div className="overflow-auto mt-2" style={{ maxHeight: 360, border: "1px solid " + P.line }}>
            {view === "workbook" ? (
              <table className="w-full" style={{ fontSize: FS.sm, color: P.text }}>
                <thead><tr>
                  <th className="text-left font-normal px-1.5" style={{ color: P.faint, position: "sticky", top: 0, background: P.panel2 }}>#</th>
                  {WB_COLS.map(([k, l]) => th(k, l))}
                  {th("mode", "mode", true)}
                </tr></thead>
                <tbody>
                  {rows.map((r, i) => {
                    const isSel = sel && keyOf(sel) === keyOf(r);
                    const tag = isRef(r) ? "REF" : "";
                    return (
                      <tr key={keyOf(r) + r.mode + i} onClick={() => selectRow(r)}
                        className="border-t cursor-pointer hover:bg-black/[0.03]"
                        style={{ borderColor: P.line, background: isSel ? P.selbg : "transparent" }}>
                        <td className="px-1.5 py-0.5 whitespace-nowrap font-mono" style={{ color: tag ? P.cyan : P.faint }}>{i + 1}{tag ? " " + tag : ""}</td>
                        {WB_COLS.map(([k, , dd]) => <td key={k} className="text-right px-1.5 font-mono">{fmt(r[k], dd)}</td>)}
                        <td className="px-1.5">{r.mode === "F" ? "fast" : "rerun"}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            ) : T ? (
              <table className="w-full" style={{ fontSize: FS.sm, color: P.text }}>
                <thead><tr>
                  <th className="text-left font-normal px-1.5" style={{ color: P.faint, position: "sticky", top: 0, background: P.panel2 }}>#</th>
                  {[["t", "t s"], ["d", "dist ft"], ["v", "speed mph"], ["ax", "AX g"], ["ay", "AY g"], ["g", "gear"]].map(([k, l]) => th(k, l))}
                </tr></thead>
                <tbody>
                  {traceIdx.map((i, j) => (
                    <tr key={j} className="border-t" style={{ borderColor: P.line }}>
                      <td className="px-1.5 py-0.5 font-mono" style={{ color: P.faint }}>{i + 1}</td>
                      <td className="text-right px-1.5 font-mono">{fmt(T.t[i], 2)}</td>
                      <td className="text-right px-1.5 font-mono">{Math.round(T.d[i]).toLocaleString()}</td>
                      <td className="text-right px-1.5 font-mono">{fmt(MPH(T.v[i]), 1)}</td>
                      <td className="text-right px-1.5 font-mono">{fmt(T.ax[i], 2)}</td>
                      <td className="text-right px-1.5 font-mono">{fmt(T.ay[i], 2)}</td>
                      <td className="text-right px-1.5 font-mono">{T.g[i]}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <div className="p-2" style={{ fontSize: FS.sm, color: P.dim }}>No trace loaded — use "load trace .csv".</div>
            )}
          </div>
          <div className="mt-1.5" style={{ fontSize: FS.cap, color: P.faint }}>
            {view === "workbook"
              ? "Scroll the list · click a header to sort · click a row to select that target (highlights its grid cell). " + (copActive
                ? "Filtered to the CoP slice the sweep explorer is showing (reference build rows always shown — endur+auto+skid+accel sum to its total)."
                : "Showing every row in the loaded workbook.")
              : "Scroll the samples · click a header to sort. The source file carries " + (T ? T.src.toLocaleString() : "—") + " samples for this event; the table shows the stored downsample the dashboard plots."}
          </div>
        </div>
      )}
    </div>
  );
}

function TabBrief({ what, source, takeaway, open, setOpen }) {
  const Cell = ({ k, color, children }) => (
    <div className="flex-1 min-w-[220px]">
      <Micro c={color} style={{ letterSpacing: "0.16em" }}>{k}</Micro>
      <div className="mt-0.5" style={{ fontSize: FS.sm, color: P.dim, lineHeight: 1.5 }}>{children}</div>
    </div>
  );
  if (!open) {
    return (
      <button onClick={() => setOpen(true)}
        className="mb-3 w-full flex items-center gap-3 border px-3 py-1.5 text-left hover:bg-black/[0.02] focus:outline-none"
        style={{ borderColor: P.line, background: P.panel2, borderLeft: "3px solid " + P.line2 }}>
        <Micro c={P.cyan} style={{ letterSpacing: "0.16em" }}>what / source / takeaway</Micro>
        <span className="truncate" style={{ fontSize: FS.sm, color: P.faint }}>{typeof what === "string" ? what : ""}</span>
        <span className="ml-auto" style={{ fontSize: FS.cap, color: P.faint }}>▾ show</span>
      </button>
    );
  }
  return (
    <div className="mb-3 flex flex-wrap gap-x-6 gap-y-2 border px-3 py-2 relative"
      style={{ borderColor: P.line, background: P.panel2, borderLeft: "3px solid " + P.line2 }}>
      <Cell k="WHAT THIS SHOWS" color={P.cyan}>{what}</Cell>
      <Cell k="DATA SOURCE" color={P.amber}>{source}</Cell>
      <Cell k="TAKEAWAY" color={P.green}>{takeaway}</Cell>
      <button onClick={() => setOpen(false)} className="absolute top-1 right-2 font-mono hover:opacity-80 focus:outline-none"
        style={{ fontSize: 9, color: P.faint }}>▴ hide</button>
    </div>
  );
}

